function makeCounter(): () => number {
  let n = 0;
  return () => ++n;
}

const threshold = 10 as const;
const isLate = (row: Row): boolean => row.deadline > threshold;   // capture typed

class Api {
  private onChange: ((row: Row) => void) | null = null;   // explicit, inspectable
  subscribe(fn: (row: Row) => void): () => void {
    this.onChange = fn;
    return () => { if (this.onChange === fn) this.onChange = null; }  // unsubscribe
  }
}
